import React from 'react';
import './Hero.css';

const Hero = () => {
  return (
    <section className="hero" id="home">
      <div className="container">
        <div className="hero-content">
          <h1 className="hero-title">
            TENSILE STRUCTURES<br />
            GERMAN HANGARS<br />
            ARCHITECTURAL SOLUTIONS
          </h1>

          <div className="hero-line"></div>

          <p className="hero-subtitle">
            Engineering precision meets architectural innovation. 
            Specialized in tensile structures, industrial tents, and German-engineered hangars.
          </p>

          <div className="hero-buttons">
            <button className="btn">VIEW PROJECTS</button>
            <button className="btn btn-outline">GET QUOTE</button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
